#define BMS_STATUS_ID 0x18FF50E5UL
#define BMS_STATUS_DLC 8U
#define BMS_STATUS_CYCLE_MS 100U
#define BMS_STATUS_EXTENDED_FRAME 1U

typedef struct {
    float pack_voltage_v;
    float pack_current_a;
} BmsStatus;

static BmsStatus g_bms_status;

void BmsStatus_OnCanRx(const CanFrame *frame)
{
    if (frame->id != BMS_STATUS_ID || frame->dlc != BMS_STATUS_DLC) {
        return;
    }
    const uint16_t voltage_raw = (uint16_t)frame->data[0] | ((uint16_t)frame->data[1] << 8);
    const int16_t current_raw = (int16_t)((uint16_t)frame->data[2] | ((uint16_t)frame->data[3] << 8));
    g_bms_status.pack_voltage_v = (float)voltage_raw * 0.1f;
    g_bms_status.pack_current_a = (float)current_raw * 0.1f;
}

#define THERMAL_STATUS_ID 0x18FF62A1UL
#define THERMAL_STATUS_DLC 8U
#define THERMAL_STATUS_CYCLE_MS 250U
#define THERMAL_STATUS_EXTENDED_FRAME 1U

typedef struct {
    float max_cell_temp_c;
    float pump_duty_pct;
} ThermalStatus;

static ThermalStatus g_thermal;

void ThermalStatus_OnCanRx(const CanFrame *frame)
{
    if (frame->id != THERMAL_STATUS_ID || frame->dlc != THERMAL_STATUS_DLC) {
        return;
    }
    const int16_t temp_raw = (int16_t)((uint16_t)frame->data[0] | ((uint16_t)frame->data[1] << 8));
    const uint8_t pump_duty_raw = frame->data[2];
    g_thermal.max_cell_temp_c = (float)temp_raw * 0.01f;
    g_thermal.pump_duty_pct = (float)pump_duty_raw * 0.5f;
}

#define CHARGE_LIMITS_ID 0x521U
#define CHARGE_LIMITS_DLC 8U
#define CHARGE_LIMITS_CYCLE_MS 20U
#define CHARGE_LIMITS_EXTENDED_FRAME 0U

typedef struct {
    float charge_current_limit_a;
    float discharge_current_limit_a;
} ChargeLimits;

static ChargeLimits g_limits;

void ChargeLimits_Transmit(CanFrame *frame)
{
    const uint16_t charge_raw = (uint16_t)lroundf(g_limits.charge_current_limit_a / 0.1f);
    const uint16_t discharge_raw = (uint16_t)lroundf(g_limits.discharge_current_limit_a / 0.1f);
    frame->id = CHARGE_LIMITS_ID;
    frame->dlc = CHARGE_LIMITS_DLC;
    frame->data[0] = (uint8_t)(charge_raw & 0xFFU);
    frame->data[1] = (uint8_t)(charge_raw >> 8);
    frame->data[2] = (uint8_t)(discharge_raw & 0xFFU);
    frame->data[3] = (uint8_t)(discharge_raw >> 8);
    frame->data[4] = 0U;
    frame->data[5] = 0U;
    frame->data[6] = 0U;
    frame->data[7] = 0U;
    Can_Send(frame);
}
